done, miss = set(), []
for d in (r['new_sources'], r['old_sources'], o['sources']):
    for i, t in NEW.items():
        if i in d: d[i] = t; done.add(i)
    for i, reps in REPL.items():
        if i in d:
            for a, b in reps:
                if a in d[i]: d[i] = d[i].replace(a, b); done.add(i)
                elif b not in d[i]: miss.append(i)
def fix(s):
    for a, b in COEF_TXT:
        if a in s and b not in s: s = s.replace(a, b)
    return s
